```js
// Minimal OpenAI-compatible chat-completions stub for reproducing a direct call
// to a Tool Search deferred tool. Turn 1 returns one structured tool call named
// STUB_TOOL with STUB_ARGS; turn 2 prints the tool result the runtime sent back
// and answers with plain text.
import { createServer } from "node:http";

const port = Number(process.env.STUB_PORT ?? 18555);
const toolName = process.env.STUB_TOOL ?? "sessions_list";
const toolArgs = process.env.STUB_ARGS ?? "{}";

function sse(res, chunks) {
  res.writeHead(200, { "content-type": "text/event-stream", "cache-control": "no-cache" });
  for (const chunk of chunks) {
    res.write(`data: ${JSON.stringify(chunk)}\n\n`);
  }
  res.end("data: [DONE]\n\n");
}

function frame(delta, finishReason = null) {
  return {
    id: "chatcmpl-stub",
    object: "chat.completion.chunk",
    created: Math.floor(Date.now() / 1000),
    model: "stub-model",
    choices: [{ index: 0, delta, finish_reason: finishReason }],
  };
}

let requestCount = 0;
createServer((req, res) => {
  if (req.method === "GET") {
    res.writeHead(200, { "content-type": "application/json" });
    res.end(JSON.stringify({ object: "list", data: [{ id: "stub-model", object: "model" }] }));
    return;
  }
  let raw = "";
  req.on("data", (part) => (raw += part));
  req.on("end", () => {
    const body = JSON.parse(raw || "{}");
    requestCount += 1;
    const offered = (body.tools ?? []).map((tool) => tool.function?.name).sort();
    console.log(`[stub] request ${requestCount}: tools offered = ${offered.join(", ")}`);
    console.log(`[stub] request ${requestCount}: "${toolName}" offered directly = ${offered.includes(toolName)}`);
    const system = (body.messages ?? []).find((message) => message.role === "system");
    const systemText = typeof system?.content === "string" ? system.content : JSON.stringify(system?.content ?? "");
    if (requestCount === 1) {
      const row = systemText.split("\n").find((line) => line.startsWith(`- ${toolName}`));
      console.log(`[stub] request 1: system prompt directory row: ${row ? row.slice(0, 90) : "(none)"}`);
    }
    if (process.env.STUB_DEBUG) {
      console.log(JSON.stringify((body.messages ?? []).slice(1), null, 1).slice(0, 4000));
    }
    const contentText = (message) =>
      typeof message.content === "string"
        ? message.content
        : (message.content ?? []).map((part) => part.text ?? "").join("");
    // A result for a tool the request does not declare is replayed as assistant text.
    const replayMarker = "[tool result id=";
    const toolResults = (body.messages ?? []).filter(
      (message) =>
        message.role === "tool" ||
        (message.role === "assistant" && contentText(message).includes(replayMarker)),
    );
    // STUB_RETRY=1 models a client that keeps repeating the direct call.
    if (toolResults.length === 0 || process.env.STUB_RETRY) {
      console.log(`[stub] request ${requestCount}: model calls ${toolName}(${toolArgs}) directly`);
      sse(res, [
        frame({
          role: "assistant",
          tool_calls: [
            {
              index: 0,
              id: "call_direct_1",
              type: "function",
              function: { name: toolName, arguments: toolArgs },
            },
          ],
        }),
        frame({}, "tool_calls"),
      ]);
      return;
    }
    const lastText = contentText(toolResults.at(-1));
    const markerAt = lastText.lastIndexOf(replayMarker);
    const text = markerAt === -1 ? lastText : lastText.slice(lastText.indexOf("] ", markerAt) + 2);
    console.log(`[stub] request ${requestCount}: tool result the model received:\n${text}`);
    if (text.includes("Call dispatch_action")) {
      console.log(`[stub] request ${requestCount}: model follows the hint and calls dispatch_action`);
      sse(res, [
        frame({
          role: "assistant",
          tool_calls: [
            {
              index: 0,
              id: "call_dispatch_1",
              type: "function",
              function: {
                name: "dispatch_action",
                arguments: JSON.stringify({ id: toolName, args: JSON.parse(toolArgs) }),
              },
            },
          ],
        }),
        frame({}, "tool_calls"),
      ]);
      return;
    }
    sse(res, [frame({ role: "assistant", content: "STUB_DONE" }), frame({}, "stop")]);
  });
}).listen(port, "127.0.0.1", () => console.log(`[stub] listening on 127.0.0.1:${port}`));
```

