```bash
#!/usr/bin/env bash
# Reproduce: a structured direct call to a deferred Tool Search tool.
# Usage: repro.sh [tools|directory] [tool-name] [json-args]
# Run from an OpenClaw source checkout root. Uses an isolated state dir and a
# local stub provider; no credentials or network access are needed.
set -euo pipefail
mode="${1:-tools}"
tool="${2:-sessions_list}"
args="${3:-{\}}"
here="$(cd "$(dirname "$0")" && pwd)"
port="${STUB_PORT:-18555}"
state="$(mktemp -d)"
export OPENCLAW_STATE_DIR="$state"
export OPENCLAW_CONFIG_PATH="$state/openclaw.json"
cat >"$OPENCLAW_CONFIG_PATH" <<EOF
{
  "agents": {
    "defaults": {
      "model": { "primary": "stub/stub-model" },
      "workspace": "$state/workspace"
    }
  },
  "models": {
    "mode": "merge",
    "providers": {
      "stub": {
        "baseUrl": "http://127.0.0.1:$port/v1",
        "apiKey": "sk-stub",
        "api": "openai-completions",
        "models": [
          {
            "id": "stub-model",
            "name": "Stub",
            "reasoning": false,
            "input": ["text"],
            "cost": { "input": 0, "output": 0, "cacheRead": 0, "cacheWrite": 0 },
            "contextWindow": 128000,
            "maxTokens": 4096
          }
        ]
      }
    }
  },
  "tools": { "toolSearch": { "mode": "$mode" }${DENY:+, \"deny\": [\"$DENY\"]} }
}
EOF
STUB_PORT="$port" STUB_TOOL="$tool" STUB_ARGS="$args" node "$here/stub-provider.mjs" &
stub_pid=$!
cleanup() {
  kill "$stub_pid" 2>/dev/null || true
  wait "$stub_pid" 2>/dev/null || true
  rm -rf "$state"
}
trap cleanup EXIT
sleep 1
echo "[repro] openclaw $(git rev-parse --short HEAD), tools.toolSearch.mode=$mode, direct call: $tool $args"
pnpm --silent openclaw agent --local --agent main --session-id "repro-$mode" \
  -m "Use the $tool tool." --json >"$state/run.json" 2>"$state/run.err" || {
  echo "[repro] agent exited non-zero"
  tail -20 "$state/run.err"
}
node -e '
const run = JSON.parse(require("fs").readFileSync(process.argv[1], "utf8"));
const texts = (run.payloads ?? run.result?.payloads ?? []).map((p) => p.text).filter(Boolean);
console.log("[repro] final reply:", JSON.stringify(texts));
' "$state/run.json" 2>/dev/null || { echo "[repro] raw output:"; head -c 2000 "$state/run.json"; }
