cat >"$OPENCLAW_CONFIG_PATH" <<EOF
{
  "gateway": { "mode": "local", "port": $gw_port, "bind": "loopback", "auth": { "mode": "token", "token": "$token" } },
  "agents": { "defaults": { "model": { "primary": "stub/stub-model" }, "workspace": "$state/workspace" } },
  "models": {
    "mode": "merge",
    "providers": {
      "stub": {
        "baseUrl": "http://127.0.0.1:$stub_port/v1",
        "apiKey": "sk-stub",
        "api": "openai-completions",
        "models": [{ "id": "stub-model", "name": "Stub", "reasoning": false, "input": ["text"],
          "cost": { "input": 0, "output": 0, "cacheRead": 0, "cacheWrite": 0 },
          "contextWindow": 128000, "maxTokens": 4096 }]
      }
    }
  },
  "tools": { "toolSearch": { "mode": "$mode" } }
}
EOF
STUB_PORT="$stub_port" STUB_TOOL="$tool" STUB_ARGS="$args" node "$here/stub-provider.mjs" &
stub_pid=$!
# Job control gives the Gateway its own process group, so cleanup reaches every child.
set -m
pnpm --silent openclaw gateway run --port "$gw_port" >"$state/gateway.log" 2>&1 &
gateway_pid=$!
set +m
cleanup() {
  # Stop the Gateway itself so the pnpm/run-node wrappers exit normally and release their locks.
  local gateway_procs
  # The Gateway runs in its own process group; find it by its listening port.
  gateway_procs="$(lsof -t -nP -iTCP:"$gw_port" -sTCP:LISTEN || true)"
  [ -n "$gateway_procs" ] && kill -TERM $gateway_procs 2>/dev/null || true
  kill -TERM "$stub_pid" 2>/dev/null || true
  for pid in $gateway_procs; do
    for _ in $(seq 1 150); do kill -0 "$pid" 2>/dev/null || break; sleep 0.2; done
  done
  kill -TERM -- "-$gateway_pid" 2>/dev/null || true
  wait "$gateway_pid" "$stub_pid" 2>/dev/null || true
  rm -rf "$state"
}
trap cleanup EXIT
for _ in $(seq 1 180); do
  if pnpm --silent openclaw gateway health --port "$gw_port" >/dev/null 2>&1; then break; fi
  sleep 1
done
echo "[repro] openclaw $(git rev-parse --short HEAD) Gateway on 127.0.0.1:$gw_port, tools.toolSearch.mode=$mode, direct call: $tool $args"
pnpm --silent openclaw agent --agent main --session-id "repro-gw-$mode" --timeout 600 \
  -m "Use the $tool tool." --json >"$state/run.json" 2>"$state/run.err" || {
  echo "[repro] agent exited non-zero"
  tail -20 "$state/run.err"
}
node -e '
const run = JSON.parse(require("fs").readFileSync(process.argv[1], "utf8"));
const texts = (run.payloads ?? run.result?.payloads ?? []).map((p) => p.text).filter(Boolean);
console.log("[repro] final reply via Gateway:", JSON.stringify(texts));
' "$state/run.json" 2>/dev/null || { echo "[repro] raw output:"; head -c 1500 "$state/run.json"; }
