## What Problem This Solves

An authorized inbound FaceTime call can be answered before OpenClaw's realtime voice path is ready. Callers hear silence and may start speaking before the assistant can respond.

Fixes #202917

## Why This Change Was Made

The FaceTime event handler now waits for the talk driver's existing provider and route readiness before answering, then checks that the call is still active. It keeps the current muted-answer and audio-activation sequence.

## User Impact

Inbound FaceTime calls keep ringing until OpenClaw is ready to speak, reducing silent openings and repeated greetings.

## Evidence

- Production event-handler boundary, pinned base `52cc86028d703a4820b688e726097842d05d2155` vs tested head `b7eee9cd62b6307fe258d016e651493d31433084`:

  ```text
  base: readiness-pending answerCalls=1; order=suppression-ready, answer-muted, provider-and-route-readiness
  head: readiness-pending answerCalls=0; order=suppression-ready, provider-and-route-readiness
  head after readiness: answerCalls=1; answer-muted then activate
  negative control: unauthorized incoming call was not answered
  ```

  The same `node scripts/test-projects.mts extensions/facetime/tests/runtime-production-proof.test.ts` harness ran on both versions. It calls the changed production event handler with a fixed inbound event and controlled helper/media boundaries. No live FaceTime call was placed or received.
- Focused regression: `node scripts/test-projects.mts extensions/facetime/tests/runtime.test.ts` passed all 25 tests, including the deferred-readiness ordering case.
- Existing `readyForAudio()` is the talk driver's readiness contract; `activateCallTalk()` already waits on it before enabling media.

<details>
<summary>Production event-handler proof source</summary>

Save this as `extensions/facetime/tests/runtime-production-proof.test.ts` and run the command above from the repository root:

```ts
import { expect, it } from "vitest";
import { resolveFaceTimeConfig } from "../src/config.js";
import { createFaceTimeCallEventHandler } from "../src/runtime-call-events.js";
import { FaceTimeCallRegistry } from "../src/runtime-state.js";
import { incomingCall } from "./fixtures.test-support.js";

it("shows the production event handler waiting before answer", async () => {
  const calls = new FaceTimeCallRegistry();
  const order: string[] = [];
  let releaseReadiness = () => {};
  let readinessEntered = () => {};
  const readiness = new Promise<void>((resolve) => {
    releaseReadiness = resolve;
  });
  const entered = new Promise<void>((resolve) => {
    readinessEntered = resolve;
  });
  let readinessCalls = 0;
  let answerCalls = 0;
  const answerResult = {
    outcome: "answered-muted",
    muted: true,
    is_uplink_muted: true,
    helpersContacted: 1,
    topologyGeneration: 1,
    topologyComplete: true,
    helperResults: [{ outcome: "answered-muted", muted: true, is_uplink_muted: true }],
  };
  const handler = createFaceTimeCallEventHandler({
    calls,
    helper: {
      answerCall: async () => {
        answerCalls += 1;
        order.push("answer-muted");
        return answerResult;
      },
    } as never,
    config: resolveFaceTimeConfig({ ownerHandles: ["owner@example.com"] }),
    logger: { info() {}, warn() {}, debug() {}, error() {} } as never,
    callControl: {
      startCallTalk: async (call) => {
        order.push("suppression-ready");
        call.talk = {
          readyForAudio: async () => {
            readinessCalls += 1;
            if (readinessCalls === 1) {
              order.push("provider-and-route-readiness");
              readinessEntered();
            }
            await readiness;
          },
        } as never;
      },
      activateCallTalk: async (call) => {
        await call.talk?.readyForAudio();
        order.push("activate");
      },
      closeCall: async () => {},
      attemptCarrierHangup: async () => {},
    } as never,
    isStopping: () => false,
    isDriverInstallPending: () => false,
    getPendingDial: () => undefined,
    clearPendingDial: async () => {},
    persistPendingDial: async () => {},
    outboundCarrierPeers: new Map(),
    cancelPendingDial: async () => {},
  });

  const processing = handler.handleCallEvent(incomingCall() as never);
  await entered;
  console.log(JSON.stringify({ phase: "readiness-pending", answerCalls, order }));
  releaseReadiness();
  await processing;
  console.log(JSON.stringify({ phase: "ready", answerCalls, order }));
  expect(answerCalls).toBe(1);

  const unauthorized = createFaceTimeCallEventHandler({
    calls: new FaceTimeCallRegistry(),
    helper: { answerCall: async () => { throw new Error("unexpected answer"); } } as never,
    config: resolveFaceTimeConfig({ ownerHandles: ["owner@example.com"] }),
    logger: { info() {}, warn() {}, debug() {}, error() {} } as never,
    callControl: {} as never,
    isStopping: () => false,
    isDriverInstallPending: () => false,
    getPendingDial: () => undefined,
    clearPendingDial: async () => {},
    persistPendingDial: async () => {},
    outboundCarrierPeers: new Map(),
    cancelPendingDial: async () => {},
  });
  await unauthorized.handleCallEvent(
    incomingCall(4, { handle: { value: "other@example.com" } }) as never,
  );
  console.log("negative-control: unauthorized incoming call was not answered");
});
```

