<details>
<summary>proof-gateway-fleet.mts</summary>

```ts
import assert from "node:assert/strict";
import { spawn } from "node:child_process";
import { mkdtemp, rename, rm, writeFile } from "node:fs/promises";
import { createServer } from "node:net";
import os from "node:os";
import path from "node:path";

const repoRoot = process.cwd();
const tempRoot = await mkdtemp(path.join(os.tmpdir(), "openclaw-gateway-fleet-proof-"));
const configPath = path.join(tempRoot, "openclaw.json");
const agentIds = ["default", ...Array.from({ length: 15 }, (_, index) => `fleet-${index}`)];
const portServer = createServer();
const port = await new Promise<number>((resolve, reject) => {
  portServer.once("error", reject);
  portServer.listen(0, "127.0.0.1", () => {
    const address = portServer.address();
    if (!address || typeof address === "string") {
      reject(new Error("failed to reserve loopback port"));
      return;
    }
    resolve(address.port);
  });
});
await new Promise<void>((resolve, reject) =>
  portServer.close((error) => (error ? reject(error) : resolve())),
);

const config = {
  gateway: { mode: "local", bind: "loopback", port, auth: { mode: "none" } },
  agents: {
    ownership: "explicit",
    defaults: { workspace: path.join(tempRoot, "workspace") },
    entries: Object.fromEntries(
      agentIds.map((id) => [id, { workspace: path.join(tempRoot, "workspace", id) }]),
    ),
  },
  plugins: { enabled: false, allow: [] },
};
const env = {
  ...process.env,
  OPENCLAW_HOME: path.join(tempRoot, "home"),
  OPENCLAW_STATE_DIR: path.join(tempRoot, "state"),
  OPENCLAW_CONFIG_PATH: configPath,
};
await writeConfig(config);

let gatewayLogs = "";
const gateway = spawn(
  process.execPath,
  [
    "--import",
    "tsx",
    "src/entry.ts",
    "gateway",
    "run",
    "--allow-unconfigured",
    "--bind",
    "loopback",
    "--port",
    String(port),
    "--ws-log",
    "compact",
  ],
  { cwd: repoRoot, env, stdio: ["ignore", "pipe", "pipe"] },
);
for (const stream of [gateway.stdout, gateway.stderr]) {
  stream?.on("data", (chunk: Buffer) => {
    gatewayLogs = (gatewayLogs + chunk.toString()).slice(-160_000);
  });
}

try {
  const health = await waitForHealth();
  assert.equal(health.coreReady, true);
  assert.equal(health.modelRuntime?.degraded, false);

  await writeConfig({ ...config, meta: { lastTouchedVersion: "2026.11.1" } });
  await waitForLog("config source revision 1 accepted (file)");
  const before = await callGateway("agents.list");

  await writeConfig({ ...config, meta: { lastTouchedVersion: "2026.11.0" } });
  await waitForLog("config source revision 2 accepted (file)");
  const after = await callGateway("agents.list");

  const project = (payload: any) =>
    payload.agents.map((agent: any) => [agent.id, agent.workspace, agent.model?.primary]);
  const beforeRows = project(before);
  const afterRows = project(after);
  const uniqueIds = new Set(afterRows.map(([id]: [string]) => id));
  const uniqueWorkspaces = new Set(afterRows.map(([, workspace]: [string, string]) => workspace));
  assert.equal(afterRows.length, agentIds.length);
  assert.equal(uniqueIds.size, agentIds.length);
  assert.equal(uniqueWorkspaces.size, agentIds.length);
  assert.deepEqual(afterRows, beforeRows);

  console.log(
    `gateway.ready coreReady=true modelRuntime.degraded=false agents=${health.agents.length}`,
  );
  console.log("config.reload revisions=1,2 accepted source=file");
  const modelSelections = new Set(afterRows.map(([, , model]: [string, string, string]) => model))
    .size;
  console.log(
    `before: agents.list count=${beforeRows.length} uniqueIds=${new Set(beforeRows.map(([id]: [string]) => id)).size} uniqueWorkspaces=${new Set(beforeRows.map(([, workspace]: [string, string]) => workspace)).size} modelSelections=${modelSelections}`,
  );
  console.log(
    `after: agents.list count=${afterRows.length} uniqueIds=${uniqueIds.size} uniqueWorkspaces=${uniqueWorkspaces.size} unchangedAfterReload=true modelSelections=${modelSelections}`,
  );
} finally {
  if (gateway.exitCode === null) {
    gateway.kill("SIGINT");
    await new Promise<void>((resolve) => gateway.once("exit", () => resolve()));
  }
  await rm(tempRoot, { recursive: true, force: true });
}

async function writeConfig(value: unknown) {
  const nextPath = `${configPath}.next`;
  await writeFile(nextPath, `${JSON.stringify(value, null, 2)}\n`);
  await rename(nextPath, configPath);
}

async function waitForHealth() {
  const deadline = Date.now() + 120_000;
  while (Date.now() < deadline) {
    try {
      const health = await callGateway("health");
      if (health.coreReady === true && health.modelRuntime?.degraded === false) {
        return health;
      }
    } catch {
      if (gateway.exitCode !== null) {
        throw new Error(`Gateway exited before ready: ${gatewayLogs.slice(-2_000)}`);
      }
    }
    await new Promise((resolve) => setTimeout(resolve, 1_000));
  }
  throw new Error(`Gateway health timed out: ${gatewayLogs.slice(-2_000)}`);
}

async function waitForLog(text: string) {
  const deadline = Date.now() + 45_000;
  while (Date.now() < deadline) {
    if (gatewayLogs.includes(text)) {
      return;
    }
    if (gateway.exitCode !== null) {
      throw new Error(`Gateway exited before ${text}: ${gatewayLogs.slice(-2_000)}`);
    }
    await new Promise((resolve) => setTimeout(resolve, 100));
  }
  throw new Error(`Gateway reload timed out waiting for ${text}`);
}

async function callGateway(method: "health" | "agents.list") {
  const child = spawn(
    process.execPath,
    ["--import", "tsx", "src/entry.ts", "gateway", "call", method, "--port", String(port), "--json"],
    { cwd: repoRoot, env, stdio: ["ignore", "pipe", "pipe"] },
  );
  let stdout = "";
  let stderr = "";
  child.stdout.on("data", (chunk: Buffer) => (stdout += chunk.toString()));
  child.stderr.on("data", (chunk: Buffer) => (stderr += chunk.toString()));
  const code = await new Promise<number | null>((resolve, reject) => {
    child.once("error", reject);
    child.once("close", resolve);
  });
  if (code !== 0) {
    throw new Error(`${method} failed (${code}): ${stderr || stdout}`);
  }
  const response = JSON.parse(stdout);
  if (response.ok === false) {
    throw new Error(`${method} returned an error: ${JSON.stringify(response.error)}`);
  }
  return response;
}
```
