import { execFileSync } from "node:child_process";
import { rawDataToString } from "openclaw/plugin-sdk/webhook-ingress";
import { WebSocketServer } from "openclaw/plugin-sdk/websocket-runtime";
import { captureScreenshot } from "./extensions/browser/src/browser/cdp.ts";

type CdpMessage = { id?: number; method?: string };
type CaptureOptions = Parameters<typeof captureScreenshot>[0] & { signal?: AbortSignal };

const capture = captureScreenshot as unknown as (options: CaptureOptions) => Promise<Buffer>;

async function listen(server: WebSocketServer): Promise<number> {
  await new Promise<void>((resolve) => server.once("listening", resolve));
  return (server.address() as { port: number }).port;
}

async function close(server: WebSocketServer): Promise<void> {
  await new Promise<void>((resolve) => server.close(() => resolve()));
}

function describe(result: PromiseSettledResult<Buffer>): string {
  return result.status === "fulfilled"
    ? `resolved:${result.value.toString("utf8")}`
    : `rejected:${result.reason instanceof Error ? result.reason.message : String(result.reason)}`;
}

async function main(): Promise<void> {
  const commit = execFileSync("git", ["rev-parse", "HEAD"], { encoding: "utf8" }).trim();
  const server = new WebSocketServer({ port: 0, host: "127.0.0.1" });
  const port = await listen(server);
  const commands: string[] = [];
  let captureSeenResolve!: () => void;
  const captureSeen = new Promise<void>((resolve) => {
    captureSeenResolve = resolve;
  });

  server.on("connection", (socket) => {
    socket.on("message", (raw) => {
      const message = JSON.parse(rawDataToString(raw)) as CdpMessage;
      const method = message.method ?? "";
      commands.push(method);
      if (method === "Page.enable" || method === "Page.bringToFront") {
        socket.send(JSON.stringify({ id: message.id, result: {} }));
      } else if (method === "Page.captureScreenshot") {
        captureSeenResolve();
      }
    });
  });

  const controller = new AbortController();
  const pending = capture({
    wsUrl: `ws://127.0.0.1:${port}/devtools/browser/PROOF`,
    timeoutMs: 1_000,
    signal: controller.signal,
  });
  await captureSeen;
  const abortStartedAt = Date.now();
  controller.abort(new Error("proof cancellation"));
  const early = await Promise.race([
    pending.then(
      () => "resolved",
      (error: unknown) => `rejected:${error instanceof Error ? error.message : String(error)}`,
    ),
    new Promise<string>((resolve) => setTimeout(() => resolve("not-rejected-before-300ms"), 300)),
  ]);
  const final = await Promise.allSettled([pending]);
  console.log(`commit=${commit}`);
  console.log(`cancelledCaptureEarly=${early} elapsedMs=${Date.now() - abortStartedAt}`);
  console.log(`cancelledCaptureFinal=${describe(final[0]!)}`);
  console.log(`commands=${commands.join(",")}`);
  await close(server);

  const control = new WebSocketServer({ port: 0, host: "127.0.0.1" });
  const controlPort = await listen(control);
  control.on("connection", (socket) => {
    socket.on("message", (raw) => {
      const message = JSON.parse(rawDataToString(raw)) as CdpMessage;
      if (message.method === "Page.captureScreenshot") {
        socket.send(
          JSON.stringify({
            id: message.id,
            result: { data: Buffer.from("PNGDATA").toString("base64") },
          }),
        );
      } else {
        socket.send(JSON.stringify({ id: message.id, result: {} }));
      }
    });
  });
  const image = await capture({
    wsUrl: `ws://127.0.0.1:${controlPort}/devtools/browser/PROOF`,
    timeoutMs: 1_000,
  });
  console.log(`successControl=${image.toString("utf8")}`);
  await close(control);
}

await main();
